import type { AtlasLink } from '@/types';

import raw from './wineAtlasLinks.json';

/**
 * Dex card -> atlas: every wine card, and the ports and sherries on the
 * spirit shelf, which are the same wines.
 *
 * Generated by scripts/build-wine-atlas-links.mjs. Eight cards carry
 * `absent` instead of links: the two vermouths, which are aromatized rather
 * than appellation wines, and v4.16's six styles made anywhere (California
 * Red Blend, New World Rosé…), which no appellation is. They say so on the
 * card rather than pointing at something approximate.
 *
 * Null prototype, read with an own-key test: the id arrives from a route,
 * and ATLAS_LINKS['constructor'] must not be the Object function (the
 * reason @/data's getDrink is written the same way).
 */
const ATLAS_LINKS: Record<string, AtlasLink> = Object.assign(
  Object.create(null) as Record<string, AtlasLink>,
  raw as unknown as Record<string, AtlasLink>,
);

export function atlasLinkFor(drinkId: string): AtlasLink | undefined {
  return Object.prototype.hasOwnProperty.call(ATLAS_LINKS, drinkId) ? ATLAS_LINKS[drinkId] : undefined;
}

let CARD_OF: Map<string, string> | null = null;

/**
 * The Dex card that IS this atlas wine, by the wine's name: the card
 * whose link names that wine and no other. Every atlas wine but two has
 * one — its generated card, the authored card that took its name (Barolo),
 * or the spirit-shelf card it is (Porto Ruby is Ruby Port) — while a card
 * that links a family (Bordeaux Blend's ten appellations) is never the
 * answer when there is one. The two are Porto Tawny and Porto Vintage,
 * which Tawny Port and Vintage Port link beside their cousins (Colheita;
 * Late Bottled Vintage and Crusted), so a wine still unclaimed after the
 * first pass takes the card that lists it. Built on first use, so the Dex
 * pays nothing for it until the atlas opens.
 */
export function cardOfAtlasWine(name: string): string | undefined {
  if (!CARD_OF) {
    const out = new Map<string, string>();
    /* Never a bottling (-wb, v4.15): Château Latour links Pauillac, and Pauillac's row opens Pauillac. */
    const ids = Object.keys(ATLAS_LINKS).filter((id) => !id.endsWith('-wb'));
    for (const id of ids) {
      const wines = ATLAS_LINKS[id].wines;
      if (wines.length === 1 && !out.has(wines[0])) out.set(wines[0], id);
    }
    for (const id of ids) for (const w of ATLAS_LINKS[id].wines) if (!out.has(w)) out.set(w, id);
    CARD_OF = out;
  }
  return CARD_OF.get(name);
}
